/// The highest derivative order of a kernel (0 for :a0 and :a1), if the kernel exists
pub fn max_derivative(kernel: &str) -> Option<i32> {
    match kernel {
        "a0" => Some(0),
        "a1" => Some(0),
        "a3" => Some(1),
        "a4" => Some(1),
        "a5" => Some(1),
        "a7" => Some(1),
        "b5" => Some(3),
        "b7" => Some(5),
        "b9" => Some(6),
        "b11" => Some(7),
        "b13" => Some(7),
        _ => None,
    }
}

/// The highest integral order m (derivative order -m) of a kernel, if the kernel exists
pub fn max_integral(kernel: &str) -> Option<i32> {
    match kernel {
        "a0" => Some(2),
        "a1" => Some(2),
        "a3" => Some(4),
        "a4" => Some(4),
        "a5" => Some(4),
        "a7" => Some(4),
        "b5" => Some(6),
        "b7" => Some(8),
        "b9" => Some(8),
        "b11" => Some(8),
        "b13" => Some(8),
        _ => None,
    }
}

// Anchoring data of integral order m, for the 2*eqs - 1 coefficients j within reach of the
// anchor (row j - 1 for coefficient j, 1-based as in ConvolutionInterpolations.jl).
// `taylor` row j: K_{m-r}(eqs - j) for r = 0 ... m-1 (Julia's _anchor_taylor_table), the
// Taylor correction of the anchored stencil weights. `entries` row j: the coefficients of
// t^0 ... t^(m-1) of the entry polynomial of coefficient j into the left tail (Julia's
// _near_anchor_entries). Both exact in Julia, rounded once to Float64.

pub struct AnchorTable {
    /// Number of rows (2*eqs - 1)
    pub rows: usize,
    /// The integral order m: the number of values in each row
    pub order: usize,
    /// Taylor values K_{m-r}(eqs - j), row by row
    pub taylor: &'static [f64],
    /// Entry polynomial coefficients, row by row, lowest power of t first
    pub entries: &'static [f64],
}

