// Ghost-point matrices of the boundary conditions. Row j gives the weights of the first
// `cols` data values next to a boundary (mean-centered, nearest first) for the j-th ghost
// point beyond that boundary. Only the first eqs - 1 rows are used.

pub struct GhostMatrix {
    /// Number of ghost points the matrix provides
    pub rows: usize,
    /// Number of data values each ghost point is computed from
    pub cols: usize,
    /// The weights, row by row
    pub values: &'static [f64],
}

pub const LINEAR_GHOST: GhostMatrix = GhostMatrix {
    rows: 9,
    cols: 2,
    values: &[
        2.0, -1.0,
        3.0, -2.0,
        4.0, -3.0,
        5.0, -4.0,
        6.0, -5.0,
        7.0, -6.0,
        8.0, -7.0,
        9.0, -8.0,
        10.0, -9.0,
    ],
};

