/// The polynomial ghost matrix of a kernel, if it has ghost points
pub fn poly_ghost_matrix(kernel: &str) -> Option<&'static GhostMatrix> {
    match kernel {
        "a3" => Some(&A3_POLY_GHOST),
        "a4" => Some(&A4_POLY_GHOST),
        "a5" => Some(&A5_POLY_GHOST),
        "a7" => Some(&A7_POLY_GHOST),
        "b5" => Some(&B5_POLY_GHOST),
        "b7" => Some(&B7_POLY_GHOST),
        "b9" => Some(&B9_POLY_GHOST),
        "b11" => Some(&B11_POLY_GHOST),
        "b13" => Some(&B13_POLY_GHOST),
        _ => None,
    }
}
